+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VeterinariansView extends VerticalLayout {
+
+    private final transient VetRepository vetRepository;
+
+    public VeterinariansView(VetRepository vetRepository) {
+        this.vetRepository = vetRepository;
+
+        setWidthFull();
+        setPadding(true);
+        setSpacing(true);
+
+        H1 heading = new H1("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE);
+
+        Paragraph introduction = new Paragraph(
+                "Meet the veterinarians at our clinic and explore their specialties.");
+        introduction.addClassNames(LumoUtility.TextColor.SECONDARY, LumoUtility.Margin.Top.NONE);
+
+        Grid<Vet> grid = new Grid<>(Vet.class, false);
+        grid.setWidthFull();
+        grid.addThemeVariants(GridVariant.NO_BORDER);
+        grid.addColumn(Vet::firstName).setHeader("First name").setAutoWidth(true);
+        grid.addColumn(Vet::lastName).setHeader("Last name").setAutoWidth(true);
+        grid.addColumn(this::specialtyNames).setHeader("Specialties").setFlexGrow(1);
+        grid.setDataProvider(DataProvider.fromCallbacks(this::fetchVets, this::countVets));
+
+        add(heading, introduction, grid);
+    }
+
+    private Stream<Vet> fetchVets(Query<Vet, Void> query) {
+        return vetRepository.findPage(query.getOffset(), query.getLimit());
+    }
+
+    private int countVets(Query<Vet, Void> query) {
+        return vetRepository.count();
+    }
+
+    private String specialtyNames(Vet vet) {
+        if (vet.specialties().isEmpty()) {
+            return "none";
+        }
+        return vet.specialties().stream()
+                .map(Specialty::name)
+                .collect(Collectors.joining(", "));
+    }
